prompt.text:
Repair the complete CommonJS source below. Export exactly `{ mergePreferences }` in the corrected source.

`mergePreferences(base, patch)` combines a complete preference object with a partial override.

`base` must be a plain object with exactly valid values for `theme` (string), `compact` (boolean), and `alerts` (a plain object containing boolean `email` and `push`). `patch` must be a plain object and may contain `theme`, `compact`, or `alerts`; `alerts` may independently contain `email` and/or `push`. Unknown own properties at either level and wrong value types throw `TypeError`. Empty patches and empty nested alert patches are valid.

An own property in `patch` overrides the corresponding base value, including falsy values. Missing properties preserve the base value. Return a new complete object whose nested `alerts` object is also always new. The result must not alias or mutate either argument, and later mutations to either input must not affect it.

```javascript
function isPlainObject(value) {
  if (value === null || typeof value !== 'object') return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

function hasOwn(object, key) {
  return Object.prototype.hasOwnProperty.call(object, key);
}

function rejectUnknown(object, allowed) {
  if (Object.keys(object).some((key) => !allowed.includes(key))) {
    throw new TypeError('unknown preference property');
  }
}

function mergePreferences(base, patch) {
  if (!isPlainObject(base) || !isPlainObject(patch)) throw new TypeError('preferences must be plain objects');
  rejectUnknown(base, ['theme', 'compact', 'alerts']);
  rejectUnknown(patch, ['theme', 'compact', 'alerts']);
  if (typeof base.theme !== 'string' || typeof base.compact !== 'boolean' || !isPlainObject(base.alerts)) {
    throw new TypeError('invalid base preferences');
  }
  rejectUnknown(base.alerts, ['email', 'push']);
  if (typeof base.alerts.email !== 'boolean' || typeof base.alerts.push !== 'boolean') {
    throw new TypeError('invalid base alerts');
  }
  if (hasOwn(patch, 'theme') && typeof patch.theme !== 'string') throw new TypeError('invalid theme patch');
  if (hasOwn(patch, 'compact') && typeof patch.compact !== 'boolean') throw new TypeError('invalid compact patch');
  if (hasOwn(patch, 'alerts')) {
    if (!isPlainObject(patch.alerts)) throw new TypeError('invalid alerts patch');
    rejectUnknown(patch.alerts, ['email', 'push']);
    if (hasOwn(patch.alerts, 'email') && typeof patch.alerts.email !== 'boolean') throw new TypeError('invalid email patch');
    if (hasOwn(patch.alerts, 'push') && typeof patch.alerts.push !== 'boolean') throw new TypeError('invalid push patch');
  }

  return {
    theme: hasOwn(patch, 'theme') ? patch.theme : base.theme,
    compact: hasOwn(patch, 'compact') ? patch.compact : base.compact,
    alerts: hasOwn(patch, 'alerts') ? { ...base.alerts, ...patch.alerts } : base.alerts
  };
}

module.exports = { mergePreferences };
```

