'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Reflect.ownKeys(api), ['mergePreferences']);
const { mergePreferences } = api;

const base = { theme: 'dark', compact: true, alerts: { email: true, push: false } };
const emptyResult = mergePreferences(base, {});
assert.deepStrictEqual(emptyResult, base);
assert.notStrictEqual(emptyResult, base);
assert.notStrictEqual(emptyResult.alerts, base.alerts);
base.theme = 'changed';
base.alerts.email = false;
assert.deepStrictEqual(emptyResult, { theme: 'dark', compact: true, alerts: { email: true, push: false } });

const base2 = { theme: 'light', compact: true, alerts: { email: true, push: true } };
const patch = { theme: '', compact: false, alerts: { email: false } };
const merged = mergePreferences(base2, patch);
assert.deepStrictEqual(merged, { theme: '', compact: false, alerts: { email: false, push: true } });
assert.notStrictEqual(merged.alerts, base2.alerts);
assert.notStrictEqual(merged.alerts, patch.alerts);
patch.theme = 'later';
patch.alerts.email = true;
base2.alerts.push = false;
assert.deepStrictEqual(merged, { theme: '', compact: false, alerts: { email: false, push: true } });

const nestedEmpty = mergePreferences({ theme: 'x', compact: false, alerts: { email: false, push: true } }, { alerts: {} });
assert.deepStrictEqual(nestedEmpty, { theme: 'x', compact: false, alerts: { email: false, push: true } });

for (const args of [
  [null, {}],
  [[], {}],
  [{ theme: 'x', compact: false, alerts: { email: true, push: false } }, null],
  [{ theme: 'x', compact: false }, {}],
  [{ theme: 1, compact: false, alerts: { email: true, push: false } }, {}],
  [{ theme: 'x', compact: 0, alerts: { email: true, push: false } }, {}],
  [{ theme: 'x', compact: false, alerts: { email: true } }, {}],
  [{ theme: 'x', compact: false, alerts: { email: true, push: false }, extra: 1 }, {}],
  [{ theme: 'x', compact: false, alerts: { email: true, push: false } }, { extra: 1 }],
  [{ theme: 'x', compact: false, alerts: { email: true, push: false } }, { theme: null }],
  [{ theme: 'x', compact: false, alerts: { email: true, push: false } }, { compact: 0 }],
  [{ theme: 'x', compact: false, alerts: { email: true, push: false } }, { alerts: null }],
  [{ theme: 'x', compact: false, alerts: { email: true, push: false } }, { alerts: { email: 1 } }],
  [{ theme: 'x', compact: false, alerts: { email: true, push: false } }, { alerts: { unknown: true } }]
]) {
  assert.throws(() => mergePreferences(...args), TypeError);
}

